#!/bin/bash

# The entire skeleton of this file was generated by Gemini flash 3.8
# Prompt:
# okay so give me a script that goes through all .scala files
# in ../ and pushes them at input of the ../../build/ binary for the compiler test


cd "$(dirname "$0")"

# --- Paths ---
BINARY="../../build/compiler"
LOG_DIR="../test_logs"

mkdir -p "$LOG_DIR"

# Ensure the compiler binary is built
if [ ! -f "$BINARY" ]; then
    echo "Error: $BINARY not found. Run 'make all' first."
    exit 1
fi

PASS="\e[32m✔ PASS\e[0m"
FAIL="\e[31m✘ FAIL\e[0m"

passed_count=0
failed_count=0

echo "============================================================"
echo "               RUNNING COMPILER TESTS"
echo -e "============================================================\n"

# Loop through every .scala file in ../
for file in ../*.scala; do
    [ -e "$file" ] || continue

    name=$(basename "$file" .scala)
    log_file="$LOG_DIR/$name.txt"

    # ==========================================================================
    # 🪟 THE OPEN WINDOW: TEST EXPECTATIONS
    # --------------------------------------------------------------------------
    # Matches against $name (the test filename without .scala).
    #
    # Settings:
    #   expected_exit   -> Exit code (0 for success, 1 lexer, 2 parser, 3+ semantic)
    #   expected_output -> Substring that must appear in stdout/stderr ("" to ignore)
    #   expected_file   -> Diffs files, fails if difference occurs ("" to ignore)
    #
    # Tips:
    #   - Use "prefix"* to match an entire category of tests at once.
    #   - The *) branch at the bottom is the fallback for normal/valid programs.
    # ==========================================================================
    case "$name" in
        "example_err_lex"*)
            expected_exit=1
            expected_output="lexical error"
            expected_file=""
            ;;

        "example_err_syn"*)
            expected_exit=2
            expected_output="syntax error"
            expected_file=""
            ;;

        "example_err_sem"*)
            expected_exit=3
            expected_output=""
            expected_file=""
            ;;

        "example_test_div_zero")
            expected_exit=4
            expected_output="division by zero"
            expected_file=""
            ;;

        *)
            # Default for unlisted tests: expect clean exit with no required text
            expected_exit=0
            expected_output=""
            expected_file=""
            ;;
    esac
    # ==========================================================================

    # Feed the .scala file to the compiler via stdin
    "$BINARY" < "$file" > "$log_file" 2>&1
    actual_exit=$?

    # --- Validate Results ---
    if [ $actual_exit -ne $expected_exit ]; then
        echo -e "  $FAIL   $name (Expected exit $expected_exit, got $actual_exit)"
        echo -e "           -> Log: $log_file\n"
        failed_count=$((failed_count + 1))

    elif [ -n "$expected_file" ] && ! diff -u "$expected_file" "$log_file" > /dev/null 2>&1; then
        echo -e "  $FAIL   $name (Output does not match $expected_file)"
        echo -e "           -> Diff command: diff -u $expected_file $log_file\n"
        failed_count=$((failed_count + 1))

    elif [ -n "$expected_output" ] && ! grep -q "$expected_output" "$log_file"; then
        echo -e "  $FAIL   $name (Missing expected text: '$expected_output')"
        echo -e "           -> Log: $log_file\n"
        failed_count=$((failed_count + 1))

    else
        echo -e "  $PASS   $name"
        passed_count=$((passed_count + 1))
    fi

done

# --- Final Summary ---
total_count=$((passed_count + failed_count))

echo "------------------------------------------------------------"
echo "Summary: $passed_count passed, $failed_count failed ($total_count total)"
echo "============================================================"

# Return non-zero if any test failed so Makefile stops
[ $failed_count -eq 0 ]
